import json,re
from pathlib import Path
root=Path('C:/dev/sistema-ats'); batches=json.loads((root/'graphify-out/.graphify_batches.json').read_text())
def build(batch, rows, links, extras=[]):
 files=batches[batch]; nodes=[]; edges=[]; ids={}
 for key,fi,entity,label,loc,*rest in rows:
  rel=str(Path(files[fi]).relative_to(root)).replace('\\','/').rsplit('.',1)[0]
  nid=re.sub('[^a-z0-9]','_',rel.lower())+'_'+entity
  ids[key]=nid
  n=dict(id=nid,label=label,file_type='document',source_file=files[fi],source_location=loc,source_url=None,captured_at=None,author=None,contributor=None)
  if rest: n.update(rest[0])
  nodes.append(n)
 for s,t,fi,loc,*rest in links:
  inferred=bool(rest)
  edges.append(dict(source=ids[s],target=ids[t],relation='semantically_similar_to' if inferred else 'references',confidence='INFERRED' if inferred else 'EXTRACTED',confidence_score=.85 if inferred else 1.,source_file=files[fi],source_location=loc,weight=1.))
 result=dict(nodes=nodes,edges=edges,hyperedges=[],input_tokens=0,output_tokens=0,coverage={f:len(Path(f).read_text(encoding='utf-8').splitlines()) for f in files})
 p=root/f'graphify-out/.graphify_candidate_{batch+1:02}.json'; p.write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf-8'); check=json.loads(p.read_text(encoding='utf-8')); print(p.name,len(check['nodes']),len(check['edges']))
 return result
